  m: { w: "Jan Molen", d: "1912-10-03", p: "Utingeradeel" },
  marriages: [{ order: 1, partner: "Jan Molen", kw: 14, date: "1912-10-03", place: "Utingeradeel", note: null, st: "A", src: [["Huwelijk Utingeradeel 1912 · Tresoar, toegang 30-38, inv. 2042, akte 35", OA + "frl:4928893c-5433-ec9b-3771-a49e3b85ac72"]] }],
