  res: [{ p: "Oudelamer", y: 1811, t: "huisman" }],
  notes: ["In 1811 liet hij in Oldelamer de naam Dijkstra inschrijven, met acht kinderen tussen 11 en 26 jaar.",
    { t: "Zijn kinderen heetten onder meer Jelle, Jeltje en Jochum: naar Jelle Jochums en Jeltje Abes, en naar Jelles vader Jochum.", k: "afgeleid" },
    { t: "Hij was een broer van Wytske Jelles (kw 243), die net als hij in Oldelamer eindigde. Zijn dochter Elizabeth (kw 79) en haar dochter Gatske (kw 121) waren dus volle nichten.", k: "afgeleid" }],
